        Debug.assert(compilerOptions);
        Debug.assert(rootFileNames);

        clearInvalidateResolutionsOfFailedLookupLocations();

        const program = getCurrentBuilderProgram();
        if (hasChangedCompilerOptions) {
            newLine = updateNewLine();
